// Data-driven verification of the 1:1 slab allocator port against real
// TypeScript runtime truth generated by tool/ts2dart/_batch108_truth.cjs.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:semi_design_flutter/src/monaco/base/common/errors.dart'
    show BugIndicatingError;
import 'package:semi_design_flutter/src/monaco/editor/browser/gpu/atlas/atlas.dart'
    as atlas;
import 'package:semi_design_flutter/src/monaco/editor/browser/gpu/atlas/textureAtlasSlabAllocator.dart'
    as slab;
import 'package:semi_design_flutter/src/monaco/editor/browser/gpu/raster/raster.dart'
    as raster;
import 'package:semi_design_flutter/src/monaco/editor/browser/gpu/atlas/textureAtlasShelfAllocator.dart'
    show AtlasCanvas, AtlasContext2D;

class _RecordingContext implements AtlasContext2D {
  final List<String> draws = <String>[];
  String _fillStyle = '';
  @override
  set fillStyle(String value) => _fillStyle = value;

  @override
  set globalAlpha(num value) {}

  @override
  void drawImage(raster.OffscreenCanvas source, num sx, num sy, num sw, num sh,
      num dx, num dy, num dw, num dh) {
    draws.add('$sx,$sy,$sw,$sh,$dx,$dy,$dw,$dh');
  }

  @override
  void fillRect(num x, num y, num w, num h) {}
}

AtlasCanvas _canvas(int w, int h, AtlasContext2D ctx) => AtlasCanvas(
      width: w,
      height: h,
      getContext: (_, [__]) => ctx,
      convertToBlob: () async => atlas.Blob(Object()),
    );

slab.TextureAtlasSlabAllocator _allocator(
        int w, int h, AtlasContext2D ctx, [Map<String, dynamic>? options]) =>
    slab.TextureAtlasSlabAllocator(
      _canvas(w, h, ctx),
      0,
      options == null
          ? null
          : slab.TextureAtlasSlabAllocatorOptions(
              slabW: options['slabW'] as num?, slabH: options['slabH'] as num?),
    );

raster.IRasterizedGlyph _glyph(int w, int h) => raster.RasterizedGlyph(
      source: raster.OffscreenCanvas(Object()),
      boundingBox: raster.BoundingBox(
          left: 0, top: 0, right: w - 1, bottom: h - 1),
      originOffset: raster.OriginOffset(x: 0, y: 0),
      fontBoundingBoxAscent: 0,
      fontBoundingBoxDescent: 0,
    );

final Map<String, dynamic> truth =
    jsonDecode(File('tool/ts2dart/batch108_truth.json').readAsStringSync())
        as Map<String, dynamic>;

void main() {
  group('TextureAtlasSlabAllocator (truth-driven)', () {
    void checkScene({
      required String key,
      required int w,
      required int h,
      Map<String, dynamic>? options,
      required List<List<int>> glyphs,
    }) {
      final Map<String, dynamic> t = truth[key] as Map<String, dynamic>;
      final ctx = _RecordingContext();
      final allocator = _allocator(w, h, ctx, options);
      final List<dynamic> expected = t['allocations'] as List<dynamic>;
      for (int i = 0; i < glyphs.length; i++) {
        final atlas.ITextureAtlasPageGlyph? g =
            allocator.allocate(_glyph(glyphs[i][0], glyphs[i][1]));
        final Object? exp = expected[i];
        if (exp == null) {
          expect(g, isNull, reason: '$key allocation $i should be undefined');
        } else {
          expect(g, isNotNull, reason: '$key allocation $i should succeed');
          final Map<String, dynamic> e = exp as Map<String, dynamic>;
          expect(
              <String, dynamic>{
                'x': g!.x, 'y': g.y, 'w': g.w, 'h': g.h,
              },
              <String, dynamic>{
                'x': e['x'], 'y': e['y'], 'w': e['w'], 'h': e['h'],
              },
              reason: '$key allocation $i');
        }
      }
      expect(ctx.draws, t['draws'] as List<dynamic>, reason: '$key draws');
      if (t.containsKey('stats')) {
        expect(allocator.getStats(), t['stats'] as String,
            reason: '$key stats');
      }
    }

    test('single allocation', () {
      checkScene(
          key: 'singleAllocation', w: 2, h: 2, glyphs: <List<int>>[<int>[1, 1]]);
    });

    test('single slab single glyph full', () {
      checkScene(
          key: 'singleSlabSingleGlyphFull',
          w: 1,
          h: 1,
          options: <String, dynamic>{'slabW': 1, 'slabH': 1},
          glyphs: <List<int>>[<int>[1, 1], <int>[1, 1]]);
    });

    test('single slab multiple glyph full', () {
      checkScene(
          key: 'singleSlabMultipleGlyphFull',
          w: 2,
          h: 2,
          options: <String, dynamic>{'slabW': 2, 'slabH': 2},
          glyphs: <List<int>>[<int>[1, 2], <int>[1, 2], <int>[1, 2]]);
    });

    test('allocate 1x1 to multiple slabs until full', () {
      checkScene(
          key: 'multipleSlabsUntilFull',
          w: 4,
          h: 2,
          options: <String, dynamic>{'slabW': 2, 'slabH': 2},
          glyphs: List<List<int>>.generate(9, (_) => <int>[1, 1]));
    });

    test('glyph too large for slab (increase slab size for first glyph)', () {
      checkScene(
          key: 'tooLargeFirstGlyph',
          w: 2,
          h: 2,
          options: <String, dynamic>{'slabW': 1, 'slabH': 1},
          glyphs: <List<int>>[<int>[2, 1]]);
    });

    test('glyph too large for slab (undefined when not first glyph)', () {
      checkScene(
          key: 'tooLargeNotFirst',
          w: 2,
          h: 2,
          options: <String, dynamic>{'slabW': 1, 'slabH': 1},
          glyphs: <List<int>>[<int>[1, 1], <int>[2, 1]]);
    });

    test('separate slabs for different sized glyphs', () {
      checkScene(
          key: 'separateSlabsDiffSizes',
          w: 4,
          h: 2,
          options: <String, dynamic>{'slabW': 2, 'slabH': 2},
          glyphs: <List<int>>[
            <int>[1, 1],
            <int>[1, 2],
            <int>[1, 2],
            <int>[1, 1]
          ]);
    });

    test('glyph too large for canvas throws BugIndicatingError', () {
      final Map<String, dynamic> t =
          truth['glyphTooLargeForCanvas'] as Map<String, dynamic>;
      expect(t['threw'], isTrue);
      final allocator = _allocator(1, 1, _RecordingContext());
      expect(() => allocator.allocate(_glyph(2, 1)),
          throwsA(isA<BugIndicatingError>()));
    });
  });
}
